rewrites:
buySignal := buySignal or chTriB or chSniB
sellSignal := sellSignal or chTriS or chSniS
// ══ ① إصلاح البوابة ═══════════════════════════════════════════════════════
// allowLong/allowShort و sfBlock يُطبَّقان عند ٢٤٣١ و٢٤٧٧ ثم تتجاوزهما ٢١ إسناد OR.
buySignal  := buySignal  and allowLong  and not sfBlock
sellSignal := sellSignal and allowShort and not sfBlock

// ══ ② مرشّح قرب قاع السوينغ ═══════════════════════════════════════════════
// قياس على ١٩٢٠٨١ شمعة (٦.٥ أشهر): حصر الدخول في اللحظات التي يكون فيها السعر
// قريباً من آخر قاع محوري يرفع النسبة ٦٠.٥١٪ ← ٦٣.٠٠٪ والصافي +٧٠٩١ ← +١٣٧٦٨،
// ورابح في ٧ أشهر من ٧. المكسب أساساً على جانب الشراء: فائضه على خط الأساس
// يقفز من +٢.٥٨ إلى +٧.٤٤ وصافيه من −٩٧٦ إلى +٥٦٩٧ — أي شراء الدعم لا اللحاق.
// الشرط المعاكس (قرب قمة السوينغ) يعطي ٥٧.٩١٪ وصافي −١٢٨٩، وهو ما يؤكد أن
// الأثر حقيقي لا مصادفة إحصائية.
swUse     = input.bool(true,   "② مرشّح قرب قاع السوينغ", group=G_MAIN_NEW)
swPivLen  = input.int(3,       "② طول المحور (شموع لكل جهة)", minval=1, maxval=20, group=G_MAIN_NEW)
swMaxDist = input.float(20.0,  "② أقصى بُعد عن القاع (نقطة)", minval=1, step=1, group=G_MAIN_NEW)
swSides   = input.string("الجهتان", "② يُطبَّق على", options=["الجهتان", "الشراء فقط"], group=G_MAIN_NEW)
swPivotLo = ta.pivotlow(low, swPivLen, swPivLen)
var float swLastLo = na
if not na(swPivotLo)
    swLastLo := swPivotLo
swDist = na(swLastLo) ? 1.0e9 : (close - swLastLo) / pointUnit
swOK   = not swUse or swDist < swMaxDist
buySignal  := buySignal  and swOK
sellSignal := sellSignal and (swSides == "الشراء فقط" ? true : swOK)
// ═══════════════════════════════════════════════════════════════════════════
